events.syntax:
if row.matches_owner(source.incarnation) and row.has_started:
    native_id = row.native_id
    if native_id in started:
        raise ValueError('Continued private native start is ambiguous')
    started[native_id] = row

if row.owner in owners and row.unresolved:
    unknown[key] = row
    eligible.add(key)

if started and (not terminal_attempted):
    with suppress(Exception, asyncio.CancelledError):
        await runner.effects._emit_event(session_id, events.ManualCompactionEnd(aborted=True))

if fragment and used + record.size > max_bytes:
    yield tuple(fragment)
    fragment, used = ([], 0)

if not binding.bind(current=current, keys=source.keys, admission=self.admission, turn=self.turn, native_id=native_id, text=sent_text, already_bound=already_bound):
    yield self._refusal(UnboundOrdinaryInputRule(), defer)
    return

if not any((record.state.pending for _, record in _records(comms))):
    fcntl.flock(lock, fcntl.LOCK_UN)
    return

if not isinstance(record, Mapping):
    if label == 'wire snapshot':
        raise ValueError('Wire snapshot JSONL record must be an object.')
    raise ValueError(f'JSONL record in {label} must be an object.')

if record is not None and (not events):
    if self.ascending and record.incomplete_tail(frontier.offset):
        break
    consumed = consumed.at_offset(self.native_position(record))
    record, events = next(projected, (None, ()))
    continue

if record.unread_reply:
    total += 1
    TranscriptReply(source, through, total).insert(database)

if has_private_wire_fields(record):
    yield (message, len(json.dumps(message.to_wire()).encode()) + 1)
else:
    message.require_retained_admission(metadata.admission_after_seq)
    yield (message, raw_size)
